import {test} from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import worker,{parseFeed,groupArticles,score,SOURCES} from '../worker/index.js';
const xml=`<rss><channel><item><title>Faille critique CVE-2026-12345</title><link>https://www.cert.ssi.gouv.fr/avis/test/</link><pubDate>Tue, 13 Oct 2026 10:00:00 GMT</pubDate><description><![CDATA[Une vulnérabilité activement exploitée. <a href="https://example.com/advisory">Avis</a>]]></description></item><item><title>Dangereux</title><link>javascript:alert(1)</link></item></channel></rss>`;
test('Le parseur conserve les références et rejette les URL exécutables',()=>{const rows=parseFeed(xml,SOURCES[0]);assert.equal(rows.length,1);assert.equal(rows[0].date,'2026-10-13T10:00:00.000Z');assert.deepEqual(rows[0].references,['https://example.com/advisory']);assert.equal(rows[0].type,'Vulnérabilité');assert.equal(rows[0].score,85);});
test('Le regroupement exige le même ensemble de CVE',()=>{const a=parseFeed(xml,SOURCES[0])[0];assert.equal(groupArticles([a,{...a,source:'Autre'}]).length,1);assert.equal(groupArticles([a,{...a,cves:['CVE-2026-12345','CVE-2026-54321']}]).length,2);});
test('Un incident sans vocabulaire critique n’obtient pas un score critique',()=>{assert.equal(score('Nouvelle recommandation ANSSI').score,30);});
test('Le HTML et le JavaScript embarqué sont valides',async()=>{const r=await worker.fetch(new Request('https://test/'),{},{});assert.equal(r.status,200);const page=await r.text();assert.ok(page.includes('Cyberveille'));assert.ok(page.includes('Collecte à la demande'));new vm.Script(page.match(/<script>([\s\S]*)<\/script>/)[1]);});
test('L’API refuse les appels IA venant d’une autre origine',async()=>{const r=await worker.fetch(new Request('https://test/api/explain',{method:'POST',headers:{Origin:'https://evil.example'},body:'{}'}),{},{});assert.equal(r.status,403);});
test('L’IA absente est signalée et ne produit pas de fausse explication',async()=>{const r=await worker.fetch(new Request('https://test/api/explain',{method:'POST',headers:{Origin:'https://test'},body:'{}'}),{},{});assert.equal(r.status,503);});
test('La collecte parcourt les lots, tolère une panne et indique le résultat partiel',async()=>{const original=globalThis.fetch;let calls=0;globalThis.fetch=async url=>{calls++;if(String(url).includes('zataz'))throw Error('offline');if(String(url).includes('services.nvd.nist.gov'))return new Response(JSON.stringify({vulnerabilities:[{cve:{id:'CVE-2026-12345',published:'2026-10-13T10:00:00Z',descriptions:[{lang:'en',value:'Critical test'}],metrics:{cvssMetricV31:[{cvssData:{baseScore:9.8}}]}}}]}));if(String(url).includes('known_exploited_vulnerabilities.json'))return new Response(JSON.stringify({vulnerabilities:[{cveID:'CVE-2026-12345',vulnerabilityName:'Test',shortDescription:'Test',requiredAction:'Patch',dateAdded:'2026-10-13'}]}));return new Response(xml);};try{let body;for(let i=0;i<Math.ceil(SOURCES.filter(s=>s.enabled).length/20);i++){const before=calls;body=await(await worker.fetch(new Request('https://test/api/feed?continue=1'),{},{})).json();assert.ok(calls-before<=20);}assert.equal(body.sources.filter(s=>s.status==='error').length,1);assert.equal(body.pendingSources,0);assert.equal(body.events.length,1);assert.equal(body.events[0].articles.length,SOURCES.filter(s=>s.enabled).length-1);}finally{globalThis.fetch=original;}});
test('Une clé OpenAI seule ne permet aucun appel payant',async()=>{const r=await worker.fetch(new Request('https://test/api/explain',{method:'POST',headers:{Origin:'https://test'},body:'{}'}),{OPENAI_API_KEY:'test-only'},{});assert.equal(r.status,503);});
test('La présence des clés n’est pas présentée comme une connexion vérifiée',async()=>{const r=await worker.fetch(new Request('https://test/api/status'),{OPENAI_API_KEY:'test-only',X_BEARER_TOKEN:'test-only',LINKEDIN_CLIENT_ID:'test-only',LINKEDIN_CLIENT_SECRET:'test-only'},{});const s=await r.json();assert.equal(s.protected,false);assert.equal(s.linkedinAvailable,false);assert.equal(s.linkedinConfigured,true);assert.ok(!JSON.stringify(s).includes('test-only'));});
test('Gemini utilise le secret dans un en-tête et restitue le texte',async()=>{const {generateExplanation}=await import('../worker/index.js');const orig=globalThis.fetch;globalThis.fetch=async(url,options)=>{assert.ok(String(url).includes('gemini-2.5-flash:generateContent'));assert.ok(!String(url).includes('fixture'));assert.equal(options.headers['x-goog-api-key'],'fixture');assert.ok(JSON.parse(options.body).systemInstruction);return new Response(JSON.stringify({candidates:[{content:{parts:[{text:'Explication simple.'}]}}]}));};try{const r=await generateExplanation('gemini',{GEMINI_API_KEY:'fixture'},[]);assert.equal(r.text,'Explication simple.');assert.equal(r.provider,'gemini');}finally{globalThis.fetch=orig;}});
test('Gemini signale les limites et les réponses vides',async()=>{const {generateExplanation}=await import('../worker/index.js');const orig=globalThis.fetch;try{globalThis.fetch=async()=>new Response(JSON.stringify({error:{status:'RESOURCE_EXHAUSTED'}}),{status:429,headers:{'Retry-After':'90'}});const r=await generateExplanation('gemini',{GEMINI_API_KEY:'fixture'},[]);assert.equal(r.code,'provider_limit');assert.equal(r.retryAfterSeconds,90);globalThis.fetch=async()=>new Response(JSON.stringify({candidates:[]}));assert.equal((await generateExplanation('gemini',{GEMINI_API_KEY:'fixture'},[])).code,'empty_response');}finally{globalThis.fetch=orig;}});
test('Gemini seul est reconnu, mais reste protégé',async()=>{const env={GEMINI_API_KEY:'fixture',GEMINI_FREE_TIER_CONFIRMED:'true'};const r=await worker.fetch(new Request('https://test/api/status'),env,{});const body=await r.json();assert.equal(body.ai,true);assert.equal(body.gemini,true);assert.equal(body.openai,undefined);const denied=await worker.fetch(new Request('https://test/api/explain',{method:'POST',headers:{Origin:'https://test'},body:'{}'}),env,{});assert.equal(denied.status,401);});
test('Les titres anglophones sont classés et le catalogue couvre plusieurs régions',async()=>{const {classify}=await import('../worker/index.js');assert.equal(classify('Critical vulnerability actively exploited'),'Vulnérabilité');assert.equal(classify('Customer data leak'),'Fuite de données');assert.ok(SOURCES.filter(s=>s.enabled).length>=18);assert.ok(SOURCES.some(s=>s.country==='JP'));});
test('La provenance bloque les adresses privées, credentials et redirections non autorisées',async()=>{const {allowedEvidenceURL}=await import('../worker/index.js');assert.equal(allowedEvidenceURL('https://127.0.0.1/'),false);assert.equal(allowedEvidenceURL('https://cisa.gov.evil.example/'),false);assert.equal(allowedEvidenceURL('https://user:pass@www.cisa.gov/'),false);assert.equal(allowedEvidenceURL('https://www.cisa.gov:444/'),false);assert.equal(allowedEvidenceURL('https://www.cisa.gov/alerts/'),true);});
test('Les références ignorent les images et distinguent une mention de divulgation',async()=>{const {extractLinks,disclosureMentions}=await import('../worker/index.js');const links=extractLinks('<a href="/photo.jpg">preuve</a><a href="https://www.cisa.gov/advisory">avis original</a><a href="javascript:alert(1)">mal</a>','https://www.zataz.com/test/');assert.equal(links.length,1);assert.ok(links[0].kind.startsWith('Référence'));const mention=disclosureMentions('The actor claims data on BreachForums.','https://www.zataz.com/test/');assert.equal(mention[0].platform,'BreachForums');assert.ok(mention[0].status.includes('non vérifié'));});
test('L’import LinkedIn exige une publication publique et un extrait',async()=>{const {manualEvent}=await import('../worker/index.js');assert.equal(manualEvent({url:'https://evil.example/',summary:'Texte suffisamment long à importer.'}),null);const e=manualEvent({url:'https://www.linkedin.com/posts/exemple',summary:'Une vulnérabilité CVE-2026-12345 est annoncée.'});assert.equal(e.type,'Vulnérabilité');assert.equal(e.date,null);assert.ok(e.source.includes('fourni'));});
test('Les opérations de provenance et traduction exigent le code d’accès',async()=>{for(const path of ['provenance','translate']){const r=await worker.fetch(new Request('https://test/api/'+path,{method:'POST',headers:{Origin:'https://test'},body:'{}'}),{},{});assert.equal(r.status,401);}});
test('Une redirection vers une cible privée n’est jamais suivie',async()=>{const original=globalThis.fetch;const calls=[];globalThis.fetch=async url=>{calls.push(String(url));return new Response('',{status:302,headers:{Location:'https://127.0.0.1/private'}});};try{const r=await worker.fetch(new Request('https://test/api/provenance',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+'b'.repeat(32)},body:JSON.stringify({id:'cve:CVE-2026-12345'})}),{APP_ACCESS_TOKEN:'b'.repeat(32)},{});assert.equal(r.status,200);const result=await r.json();assert.ok(result.pages.every(p=>p.status==='not_fetched'));assert.ok(calls.every(url=>!url.includes('127.0.0.1')));}finally{globalThis.fetch=original;}});
async function translationHarness(events,respond){
 const page=await (await worker.fetch(new Request('https://test/'),{},{})).text();
 const script=page.match(/<script>([\s\S]*)<\/script>/)[1];
 const code=script.slice(script.indexOf('let translationRunning='),script.indexOf('function render(){'));
 const timers=[];const elements=new Map();const requests=[];
 const context=vm.createContext({data:{mode:'live',events},translations:new Map(),accessToken:'fixture-private-code',connectionStatus:{ai:true},document:{hidden:false,addEventListener(){}},$:selector=>{if(!elements.has(selector))elements.set(selector,{value:'gemini',textContent:''});return elements.get(selector);},setTimeout:fn=>{timers.push(fn);return timers.length;},clearTimeout(){},render(){},fetch:async(url,options)=>{const input=JSON.parse(options.body);requests.push(input);return respond(input);}});
 new vm.Script(code).runInContext(context);
 return {context,timers,elements,requests,run:()=>vm.runInContext('startAutoTranslation()',context)};
}
test('La traduction automatique enchaîne tout le fil au-delà de douze articles',async()=>{const events=Array.from({length:25},(_,i)=>({id:'event-'+i,language:'en'}));const h=await translationHarness(events,async input=>new Response(JSON.stringify({translations:input.ids.map(id=>({id,title:'Titre français',summary:'Résumé français'}))})));await h.run();while(h.timers.length)await h.timers.shift()();assert.deepEqual(h.requests.map(r=>r.ids.length),[12,12,1]);assert.equal(h.context.translations.size,25);assert.equal(h.requests[0].provider,'gemini');});
test('Un quota fournisseur suspend les traductions sans boucle de requêtes payantes',async()=>{const h=await translationHarness([{id:'one',language:'en'}],async()=>new Response(JSON.stringify({error:'Quota épuisé',code:'insufficient_quota'}),{status:429}));await h.run();await h.run();assert.equal(h.requests.length,1);assert.equal(h.timers.length,0);assert.ok(h.elements.get('#translation-status').textContent.includes('suspendue'));});
test('Aucune traduction payante ne démarre avant le déverrouillage',async()=>{const h=await translationHarness([{id:'one',language:'en'}],async()=>{throw Error('Appel interdit');});h.context.accessToken='';await h.run();assert.equal(h.requests.length,0);assert.ok(h.elements.get('#translation-status').textContent.includes('Déverrouillez'));});
test('Les guides OSINT et pentest ont un thème distinct du type d’incident',async()=>{const {technicalTopic}=await import('../worker/index.js');assert.equal(technicalTopic('OSINT reverse image geolocation'),'OSINT');assert.equal(technicalTopic('Burp Suite penetration testing lab'),'Pentest');assert.equal(technicalTopic('DFIR incident response report'),'Investigation');assert.equal(technicalTopic('YARA detection engineering'),'Défense');const source=SOURCES.find(s=>s.id==='portswigger');const rows=parseFeed(xml,source);assert.equal(rows[0].technical,true);assert.equal(rows[0].topic,'Pentest');assert.equal(rows[0].type,'Vulnérabilité');});
function memoryStore(){const values=new Map();return {values,async get(k){return structuredClone(values.get(k));},async put(k,v){assert.ok(JSON.stringify(v).length<128000);values.set(k,structuredClone(v));},async list({prefix='',limit=1000}={}){return new Map([...values].filter(([k])=>k.startsWith(prefix)).slice(0,limit).map(([k,v])=>[k,structuredClone(v)]));},async delete(k){values.delete(k);},async setAlarm(t){this.alarmAt=t;}};}
test('Une reprise de lien est reliée au dossier, sans attribuer une confirmation indépendante',async()=>{const {relatedEvidence}=await import('../worker/index.js');const a={id:'one',date:'2026-10-15T12:00:00Z',title:'Publication initiale',articles:[{url:'https://x.com/i/web/status/1',references:['https://www.cisa.gov/avis'],cves:[]}]};const b={id:'two',title:'Rapport technique',articles:[{url:'https://www.cisa.gov/avis',references:[],cves:[]}]};const related=relatedEvidence(a,[a,b]);assert.equal(related.length,1);assert.equal(related[0].matchScore,90);assert.ok(related[0].relation.includes('vérifier'));});
