test('Les publications Bright Data sont normalisées et attribuées seulement aux profils suivis',async()=>{const {normalizeSocialRows}=await import('../worker/index.js');const x=normalizeSocialRows('x',[{user_posted:'fuitesinfos',id:'1234',description:'Fuite de données signalée publiquement',date_posted:'2026-10-15T12:00:00Z',url:'https://x.com/fuitesinfos/status/1234?tracking=yes'},{user_posted:'notfollowed',id:'9',description:'ignore',url:'https://x.com/notfollowed/status/9'}]);assert.equal(x.length,1);assert.equal(x[0].url,'https://x.com/i/web/status/1234');const li=normalizeSocialRows('linkedin',[{url:'https://www.linkedin.com/posts/example-activity-12345678-test',user_url:'https://www.linkedin.com/in/anis-ayari',post_text:'Une publication technique suffisamment détaillée',date_posted:'2026-10-15T10:00:00Z'}]);assert.equal(li.length,1);});
test('Les collectes Bright Data persistent et ne sont pas relancées dans le même intervalle',async()=>{const {SocialStore}=await import('../worker/index.js');const storage=memoryStore();const env={BRIGHTDATA_TOKEN:'fixture',BRIGHTDATA_FREE_ONLY_CONFIRMED:'true'};const original=globalThis.fetch;let starts=0;globalThis.fetch=async(url,options)=>{assert.equal(options.headers.Authorization,'Bearer fixture');assert.ok(String(url).startsWith('https://api.brightdata.com/'));if(options.method==='POST'){starts++;assert.ok(String(url).includes('limit_per_input='));return new Response(JSON.stringify({snapshot_id:starts===1?'snapX':'snapLI'}));}if(String(url).includes('/progress/'))return new Response(JSON.stringify({status:'ready'}));return new Response(JSON.stringify(String(url).includes('snapX')?[{user_posted:'fuitesinfos',description:'Fuite signalée publiquement',date_posted:new Date().toISOString(),url:'https://x.com/fuitesinfos/status/12345'}]:[]));};try{let obj=new SocialStore({storage},env);await obj.fetch(new Request('https://internal/tick'));assert.equal(starts,2);await obj.fetch(new Request('https://internal/tick'));assert.equal(starts,2);obj=new SocialStore({storage},env);const result=await (await obj.fetch(new Request('https://internal/data'))).json();assert.equal(result.articles.length,1);assert.equal(result.budget.used,39);assert.ok(!JSON.stringify(result).includes('fixture'));}finally{globalThis.fetch=original;}});
test('Apify et l’API X officielle ne sont jamais lancés en mode gratuit',async()=>{const original=globalThis.fetch;let calls=0;globalThis.fetch=async()=>{calls++;throw Error('Appel payant interdit');};try{const {SocialStore}=await import('../worker/index.js');await new SocialStore({storage:memoryStore()},{APIFY_TOKEN:'fixture'}).fetch(new Request('https://internal/tick'));const r=await worker.fetch(new Request('https://test/api/x',{method:'POST',headers:{Origin:'https://test',Authorization:'Bearer '+'b'.repeat(32)}}),{X_BEARER_TOKEN:'fixture',APP_ACCESS_TOKEN:'b'.repeat(32)},{});assert.equal(r.status,403);assert.equal(calls,0);}finally{globalThis.fetch=original;}});
test('Aucun lancement Bright Data sans confirmation du compte sans fonds',async()=>{const {SocialStore}=await import('../worker/index.js');const original=globalThis.fetch;let calls=0;globalThis.fetch=async()=>{calls++;throw Error('interdit');};try{await new SocialStore({storage:memoryStore()},{BRIGHTDATA_TOKEN:'fixture'}).fetch(new Request('https://internal/tick'));assert.equal(calls,0);const status=await (await worker.fetch(new Request('https://test/api/status'),{OPENAI_API_KEY:'fixture',GEMINI_API_KEY:'fixture'},{})).json();assert.equal(status.ai,false);assert.equal(status.openai,undefined);assert.equal(status.gemini,false);assert.equal(status.freeOnly,true);}finally{globalThis.fetch=original;}});
