test('Les anciennes réservations HTTP 400 sont libérées une fois et les refus ne bloquent pas le nouveau format',async()=>{const {SocialStore}=await import('../worker/index.js');const storage=memoryStore();const month=new Date().toISOString().slice(0,7);await storage.put('state',{platforms:{x:{status:'error',message:'Bright Data indisponible (HTTP 400)',nextAt:Date.now()+6*3600000},linkedin:{status:'error',message:'Bright Data indisponible (HTTP 400)',nextAt:Date.now()+86400000}},budget:{month,used:39}});const original=globalThis.fetch;let calls=0;globalThis.fetch=async(url,options)=>{calls++;const input=JSON.parse(options.body);assert.ok(input.every(row=>Object.keys(row).join(',')==='url'));assert.ok(String(url).includes('limit_per_input='));return new Response(JSON.stringify({error:'Unsupported discover_by parameter'}),{status:400});};try{const object=new SocialStore({storage},{BRIGHTDATA_TOKEN:'fixture',BRIGHTDATA_FREE_ONLY_CONFIRMED:'true'});await object.fetch(new Request('https://internal/tick'));let data=await (await object.fetch(new Request('https://internal/data'))).json();assert.equal(calls,2);assert.equal(data.budget.used,0);assert.ok(data.platforms.x.message.includes('Unsupported discover_by'));await object.fetch(new Request('https://internal/tick'));data=await (await object.fetch(new Request('https://internal/data'))).json();assert.equal(calls,2);assert.equal(data.budget.used,0);}finally{globalThis.fetch=original;}});
test('Consulter le suivi importe les collectes terminées sans lancer de nouvelle extraction',async()=>{const {SocialStore}=await import('../worker/index.js');const storage=memoryStore();await storage.put('state',{platforms:{x:{status:'starting',pending:{id:'snapshotX',started:Date.now()-120000,reserved:30},nextAt:Date.now()+3600000},linkedin:{}},budget:{month:new Date().toISOString().slice(0,7),used:30}});let calls=0;const original=globalThis.fetch;globalThis.fetch=async(url,options)=>{calls++;assert.ok(!options.method);if(String(url).includes('/progress/'))return new Response(JSON.stringify({status:'ready'}));return new Response(JSON.stringify([{user_posted:'fuitesinfos',description:'Une publication publique cyber détaillée',date_posted:new Date().toISOString(),url:'https://x.com/fuitesinfos/status/98765'}]));};try{const r=await new SocialStore({storage},{BRIGHTDATA_TOKEN:'fixture',BRIGHTDATA_FREE_ONLY_CONFIRMED:'true'}).fetch(new Request('https://internal/data?poll=1'));const data=await r.json();assert.equal(data.articles.length,1);assert.equal(data.platforms.x.receivedCount,1);assert.equal(data.platforms.x.lastCount,1);assert.equal(data.platforms.x.status,'ready');assert.equal(data.platforms.x.pending,undefined);assert.equal(calls,2);assert.equal(data.platforms.linkedin.pending,undefined);}finally{globalThis.fetch=original;}});
test('Le suivi reste en attente si Bright Data prépare encore le fichier et ne duplique pas la collecte',async()=>{const {SocialStore}=await import('../worker/index.js');const storage=memoryStore();await storage.put('state',{platforms:{x:{status:'starting',pending:{id:'snapshotX',started:Date.now()-120000,reserved:30},nextAt:Date.now()+3600000},linkedin:{}},budget:{month:new Date().toISOString().slice(0,7),used:30}});const original=globalThis.fetch;let calls=0;globalThis.fetch=async(url,options)=>{calls++;assert.ok(!options.method);return new Response(JSON.stringify(String(url).includes('/progress/')?{status:'ready'}:{status:'building'}));};try{const obj=new SocialStore({storage},{BRIGHTDATA_TOKEN:'fixture',BRIGHTDATA_FREE_ONLY_CONFIRMED:'true'});let data=await (await obj.fetch(new Request('https://internal/data?poll=1'))).json();assert.equal(data.platforms.x.status,'building');assert.ok(data.platforms.x.pending);await obj.fetch(new Request('https://internal/data?poll=1'));assert.equal(calls,2);}finally{globalThis.fetch=original;}});
