test('Les parcours sont progressifs, sourcés et utilisables sans IA',async()=>{const {LEARNING_TRACKS}=await import('../worker/index.js');assert.equal(LEARNING_TRACKS.length,10);const ids=new Set();for(const track of LEARNING_TRACKS){assert.deepEqual(track.lessons.map(l=>l.level),[1,2,3]);assert.ok(track.sources.every(url=>url.startsWith('https://')));for(const lesson of track.lessons){assert.ok(!ids.has(lesson.id));ids.add(lesson.id);assert.ok(lesson.concept.length>200);assert.ok(lesson.steps.length>=4);assert.ok(lesson.question&&lesson.answer&&lesson.prerequisite);}}assert.equal(ids.size,30);const html=await(await worker.fetch(new Request('https://test/'),{},{})).text();assert.ok(html.includes('data-view="tutorials"'));assert.ok(!html.includes('__TRACKS__'));assert.ok(!html.includes('__LEARNING_MATCH__'));});
